import{_ as a,o,c as i,ae as t}from"./chunks/framework.vXWZTEWX.js";const p=JSON.parse('{"title":"ADR 015: Estrategia de Despliegue en Nube (Hugging Face Spaces)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/015-cloud-deployment.md","filePath":"adr/015-cloud-deployment.md"}'),n={name:"adr/015-cloud-deployment.md"};function s(r,e,l,d,c,u){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-015-estrategia-de-despliegue-en-nube-hugging-face-spaces" tabindex="-1">ADR 015: Estrategia de Despliegue en Nube (Hugging Face Spaces) <a class="header-anchor" href="#adr-015-estrategia-de-despliegue-en-nube-hugging-face-spaces" aria-label="Permalink to &quot;ADR 015: Estrategia de Despliegue en Nube (Hugging Face Spaces)&quot;">​</a></h1><h2 id="estado" tabindex="-1">Estado <a class="header-anchor" href="#estado" aria-label="Permalink to &quot;Estado&quot;">​</a></h2><p>Aceptado</p><h2 id="contexto" tabindex="-1">Contexto <a class="header-anchor" href="#contexto" aria-label="Permalink to &quot;Contexto&quot;">​</a></h2><p>TenderCheck AI requiere un entorno de despliegue que soporte:</p><ol><li><strong>Ejecución de Docker</strong>: Para orquestar Node.js + Ollama.</li><li><strong>Aceleración GPU</strong>: Para la inferencia de modelos de embeddings (<code>nomic-embed-text</code>) y LLM (<code>mistral</code>) en tiempo razonable.</li><li><strong>Coste</strong>: Gratuito o de bajo coste para la demostración del TFM.</li><li><strong>Simplicidad</strong>: Despliegue automatizado desde Git.</li></ol><h2 id="decision" tabindex="-1">Decisión <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decisión&quot;">​</a></h2><p>Se ha seleccionado <strong>Hugging Face Spaces</strong> utilizando el SDK de <strong>Docker</strong>.</p><h3 id="detalles-de-implementacion" tabindex="-1">Detalles de Implementación <a class="header-anchor" href="#detalles-de-implementacion" aria-label="Permalink to &quot;Detalles de Implementación&quot;">​</a></h3><ol><li><strong>Imagen Base</strong>: <code>nvidia/cuda:12.1.0-base-ubuntu22.04</code> para soporte nativo de GPU.</li><li><strong>Gestión de Procesos</strong>: Script <code>start.sh</code> personalizado para ejecutar Ollama en segundo plano (<code>nohup</code>) antes de iniciar la aplicación Node.js.</li><li><strong>Persistencia</strong>: Inicialmente efímera. Los modelos se pre-descargan en el <code>Dockerfile</code> (<code>RUN ollama pull ...</code>) para evitar tiempos de espera en tiempo de ejecución, aunque esto aumenta el tamaño de la imagen.</li><li><strong>Networking</strong>: La aplicación escucha en <code>0.0.0.0:7860</code> (puerto estándar de HF).</li><li><strong>Frontend</strong>: Servido estáticamente por el backend de Express para simplificar la arquitectura a un solo contenedor.</li></ol><h2 id="consecuencias" tabindex="-1">Consecuencias <a class="header-anchor" href="#consecuencias" aria-label="Permalink to &quot;Consecuencias&quot;">​</a></h2><h3 id="positivas" tabindex="-1">Positivas <a class="header-anchor" href="#positivas" aria-label="Permalink to &quot;Positivas&quot;">​</a></h3><ul><li>Acceso gratuito a GPU (T4) en el tier básico de HF (sujeto a disponibilidad).</li><li>Despliegue atómico (Frontend + Backend + IA en una unidad).</li><li>SSL/TLS gestionado automáticamente por Hugging Face.</li></ul><h3 id="negativas" tabindex="-1">Negativas <a class="header-anchor" href="#negativas" aria-label="Permalink to &quot;Negativas&quot;">​</a></h3><ul><li><strong>Tiempo de Arranque</strong>: La inicialización del contenedor y la carga de modelos en VRAM puede tomar tiempo, causando timeouts en los health checks si no se optimiza.</li><li><strong>Espacio en Disco</strong>: Las imágenes son pesadas (&gt;6GB), lo que ralentiza el ciclo de construcción.</li></ul><h2 id="alternativas-consideradas" tabindex="-1">Alternativas Consideradas <a class="header-anchor" href="#alternativas-consideradas" aria-label="Permalink to &quot;Alternativas Consideradas&quot;">​</a></h2><ul><li><strong>Google Cloud Run</strong>: Descartado por la complejidad de configurar GPU y costes asociados.</li><li><strong>Vercel/Netlify</strong>: Descartados por la falta de soporte para ejecutar binarios persistentes como Ollama.</li></ul>',17)])])}const m=a(n,[["render",s]]);export{p as __pageData,m as default};
